at::Tensor bilinear_upsample_custom_impl_npu(const at::Tensor& self) {
    TORCH_CHECK(self.dim() == 4, "Expected input to be 4D [N,C,H,W]");
    auto sizes = self.sizes();
    std::vector<int64_t> out_sizes = {sizes[0], sizes[1], sizes[2] * 2, sizes[3] * 2};
    at::Tensor result = at::empty(out_sizes, self.options());
    EXEC_NPU_CMD(aclnnBilinearUpsampleCustom, self, result);
    return result;
}

